    sr=[i for i,r in enumerate(grid) if r.count(sep)>w//2]
    sc=[j for j in range(w) if sum(grid[i][j]==sep for i in range(h))>h//2]
    rs=[0]+[i+1 for i in sr]; re=sr+[h]
    cs=[0]+[j+1 for j in sc]; ce=sc+[w]
    for k,(r0,r1) in enumerate(zip(rs,re)):
