        tile=[row[c0:c1] for row in grid[r0:r1]]
        if len(tile)==len(tile[0]) and any(x!=bg for row in tile for x in row) and all(tile[i][j]==tile[j][i] for i in range(len(tile)) for j in range(len(tile))):
          return [row[sc[l-1] if l else c0:sc[l] if l<len(sc) else c1] for row in grid[sr[k-1] if k else r0:sr[k] if k<len(sr) else r1]]

